    within(triage_column) { find(".cards__expander").click }
    assert_selector "##{dom_id(columns(:writebook_triage))}.is-expanded"

    card = cards(:buy_domain)
    card_id = dom_id(card, :article)
    triage_id = dom_id(columns(:writebook_triage))

    # Block fetch temporarily to inspect state right after drop (before save completes)
    page.execute_script(<<~JS)
      window._originalFetch = window.fetch;
      window._pendingFetches = [];
      window.fetch = function(...args) {
        return new Promise((resolve) => {
          window._pendingFetches.push(() => resolve(window._originalFetch.apply(this, args)));
        });
      };
    JS

    find("##{card_id}").drag_to(triage_column)

    # State immediately after drop (while save is still in-flight!)
    state_at_drop = page.evaluate_script(<<~JS)
      (() => {
        const col = document.getElementById("#{triage_id}");
        const cardEl = document.getElementById("#{card_id}");
        const cards = Array.from(col.querySelectorAll(".card")).map(c => ({
          id: c.id,
