    puts "STATE AT DROP (before save):"
    pp state_at_drop

    # Now release the blocked fetch and wait for save + frame reload to complete
    page.execute_script(<<~JS)
      window.fetch = window._originalFetch;
      window._pendingFetches.forEach(fn => fn());
