require "application_system_test_case"

class DragAndDropTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  setup do
    sign_in_as(users(:david))
    @board = boards(:writebook)
  end

  def assert_instant_drop_without_shifting(card_el, source_col, target_col)
    source_id = source_col[:id]
    target_id = target_col[:id]
    card_id = card_el[:id]

    page.execute_script(<<~JS)
      window._originalFetch = window.fetch;
      window._pendingFetches = [];
      window.fetch = function(...args) {
        return new Promise((resolve) => {
          window._pendingFetches.push(() => resolve(window._originalFetch.apply(this, args)));
        });
      };
    JS

    card_el.drag_to(target_col)

    capture_js = <<~JS
      (() => {
        const src = document.getElementById("#{source_id}");
        const tgt = document.getElementById("#{target_id}");
        const cardEl = document.getElementById("#{card_id}");
        const snapshot = (col) => ({
          expanded: col.classList.contains("is-expanded"),
          collapsed: col.classList.contains("is-collapsed"),
          count: col.querySelector(".cards__expander-count")?.textContent,
          cardIds: Array.from(col.querySelectorAll(".card")).map(c => c.id),
          cardRects: Array.from(col.querySelectorAll(".card")).map(c => c.getBoundingClientRect().toJSON()),
          cardColors: Array.from(col.querySelectorAll(".card")).map(c => getComputedStyle(c).getPropertyValue("--card-color").trim()),
          blankSlateVisible: Array.from(col.querySelectorAll(".blank-slate")).some(b => b.checkVisibility())
        });
        return {
          inTarget: tgt.contains(cardEl),
          inSource: src.contains(cardEl),
          source: snapshot(src),
          target: snapshot(tgt)
        };
      })()
    JS

    state_at_drop = page.evaluate_script(capture_js)
    assert state_at_drop["inTarget"], "Card should immediately be in target column on drop before save"
    assert_not state_at_drop["inSource"], "Card should immediately leave source column on drop before save"

    page.execute_script(<<~JS)
      window.fetch = window._originalFetch;
      window._pendingFetches.forEach(fn => fn());
    JS

    sleep 0.4

    state_after_save = page.evaluate_script(capture_js)
    assert_equal state_at_drop, state_after_save
  end

  test "instant drop without shifting across all column types" do
    visit board_url(@board)

    maybe_col = find("#maybe")
    triage_col = find("##{dom_id(columns(:writebook_triage))}")
    in_progress_col = find("##{dom_id(columns(:writebook_in_progress))}")
    on_hold_col = find("##{dom_id(columns(:writebook_on_hold))}")
    not_now_col = find("#not-now")
    done_col = find("#closed-cards")

    # 1. Expand On Hold (empty column) and drag buy_domain from Maybe into On Hold
    within(on_hold_col) { find(".cards__expander").click }
    sleep 0.35
    assert_instant_drop_without_shifting(find("##{dom_id(cards(:buy_domain), :article)}"), maybe_col, on_hold_col)

    # 2. Drag buy_domain from On Hold (now becomes empty!) back to Maybe (now becomes non-empty!)
    assert_instant_drop_without_shifting(find("##{dom_id(cards(:buy_domain), :article)}"), on_hold_col, maybe_col)

    # 3. Expand Triage (has golden logo + normal layout) and drag buy_domain from Maybe into Triage
    within(triage_col) { find(".cards__expander").click }
    sleep 0.35
    assert_instant_drop_without_shifting(find("##{dom_id(cards(:buy_domain), :article)}"), maybe_col, triage_col)

    # 4. Drag buy_domain from Triage into Not Now (collapsed)
    assert_instant_drop_without_shifting(find("##{dom_id(cards(:buy_domain), :article)}"), triage_col, not_now_col)

    # 5. Expand Not Now and drag buy_domain into Done (collapsed)
    within(not_now_col) { find(".cards__expander").click }
    sleep 0.35
    assert_instant_drop_without_shifting(find("##{dom_id(cards(:buy_domain), :article)}"), not_now_col, done_col)

    # 6. Expand Done and drag shipping (closed card) into Maybe
    within(done_col) { find(".cards__expander").click }
    sleep 0.35
    assert_instant_drop_without_shifting(find("##{dom_id(cards(:shipping), :article)}"), done_col, maybe_col)
  end
end
